fast_pseudocode:
# Lambda grid re-enables autotuner → XBLOCK swept, optimal config selected
@triton.autotune(configs=[...XBLOCK configs...], key=['xnumel','r0_numel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    R0_BLOCK: tl.constexpr = 1024   # unchanged
    ...

grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # lambda → autotuner controls XBLOCK
kernel[grid](...)   # no explicit XBLOCK kwarg; autotuner injects it

